'use client';
const require_dialog_trigger_context = require("./dialog-trigger-context.cjs");
const require_dialog = require("./dialog.cjs");
const require_dialog_block = require("./dialog-block.cjs");
const require_dialog_trigger = require("./dialog-trigger.cjs");
//#region src/components/dialog/index.ts
/**
* Dialog component, used to display a Dialog dialog.
*
* @example
* <Dialog.TriggerContext>
*   <Dialog.Trigger>Open Dialog</Dialog.Trigger>
*   <Dialog>
*     <Dialog.Block>
*       Content
*     </Dialog.Block>
*   </Dialog>
* </Dialog.TriggerContext>
*/
const DialogComponent = Object.assign(require_dialog.Dialog, {
	Block: require_dialog_block.DialogBlock,
	TriggerContext: require_dialog_trigger_context.DialogTriggerContext,
	Trigger: require_dialog_trigger.DialogTrigger
});
DialogComponent.Block.displayName = "Dialog.Block";
DialogComponent.TriggerContext.displayName = "Dialog.TriggerContext";
DialogComponent.Trigger.displayName = "Dialog.Trigger";
//#endregion
exports.Dialog = DialogComponent;
exports.DialogBlock = require_dialog_block.DialogBlock;
exports.DialogTrigger = require_dialog_trigger.DialogTrigger;
exports.DialogTriggerContext = require_dialog_trigger_context.DialogTriggerContext;
